def _get_token(self) -> str:
    """Get tenant access token"""
    if self._token:
        return self._token

    resp = requests.post(AUTH_API, json={
        "app_id": self.app_id,
        "app_secret": self.app_secret
    })
    resp.raise_for_status()
    data = resp.json()

    if data.get("code") != 0:
        raise Exception(f"Auth failed: {data}")

    self._token = data["tenant_access_token"]

